 "content": "def transform(grid):
    """Reflect the 4-pattern downward for a plus marker, otherwise rightward."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not cells or not markers:
        return out
    top = min(r for r, _ in cells)
    bottom = max(r for r, _ in cells)
    left = min(c for _, c in cells)
    right = max(c for _, c in cells)
    marker_rows = [r for r, _ in markers]
    marker_cols = [c for _, c in markers]
    # The plus marker encodes a vertical reflection; arrow-like markers encode horizontal reflection.
    plus = (len(markers) == 6 and len(set(marker_rows)) == 3 and len(set(marker_cols)) == 4
            and sorted(sum(1 for r, c in markers if r == rr) for rr in set(marker_rows)) == [1, 4, 1])
    for r, c in markers:
        out[r][c] = 0
    if plus:
        motif = [grid[r][left:right + 1] for r in range(top, bottom + 1)]
        for i, row in enumerate(reversed(motif), start=bottom + 1):
            if i < h:
                for j, value in enumerate(row, start=left):
                    if value == 4 and j < w:
                        out[i][j] = 4
    else:
        for r, c in cells:
            reflected_c = 2 * right + 1 - c
            if 0 <= reflected_c < w:
                out[r][reflected_c] = 4
    return out
