    """Reflect the 4-pattern toward the side selected by the 6-marker geometry."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out

    top = min(r for r, _ in fours)
    bottom = max(r for r, _ in fours)
    left = min(c for _, c in fours)
    right = max(c for _, c in fours)
    marker_rows = sorted({r for r, _ in sixes})
    row_profile = [sum(r == rr for r, _ in sixes) for rr in marker_rows]
    marker_center_col = sum(c for _, c in sixes) / len(sixes)
    source_center_col = (left + right) / 2

    for r, c in sixes:
        out[r][c] = 0

    if row_profile == [1, 4, 1]:
        # The centered cross selects a vertical reflection. Its lateral offset
        # selects the side when it is distinctly displaced from the 4-pattern.
        if marker_center_col > source_center_col + 1:
            for r, c in fours:
                rr = 2 * top - 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
        else:
            for r, c in fours:
                rr = 2 * bottom + 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
    elif row_profile == [3, 1, 1]:
        # A T-shaped marker selects a rightward reflection.
        for r, c in fours:
            cc = 2 * right + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif row_profile == [1, 1, 3]:
        # An inverted T selects a leftward reflection.
        for r, c in fours:
            cc = 2 * left - 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    return out
